//! Guest side of the ABI: the [`Plugin`] trait and the exports generated by
//! [`register_plugin!`](crate::register_plugin).

use std::cell::RefCell;

use crate::abi::{
    self, CommandInput, HttpResponse, LoadInfo, McpToolInput, McpToolOutput, NavigationEvent,
    OmniboxInput, OmniboxOutput, PageMessageInput, PageMessageOutput, RequestInput, RequestOutput,
    SettingChanged, hook,
};

/// Implement the hooks you need; every method has a default that does
/// nothing (requests are allowed).
///
/// Hooks run on the host's plugin thread under a fuel (instruction)
/// budget: keep them short. Panics trap the instance; the host restarts it
/// and disables the plugin after repeated faults.
pub trait Plugin {
    /// Called once after instantiation, with the current settings.
    fn load(&mut self, _info: LoadInfo) {}
    /// Called before the plugin is disabled or reloaded.
    fn unload(&mut self) {}
    /// The user changed a setting on the Plugins page.
    fn setting_changed(&mut self, _key: String, _value: abi::SettingValue) {}
    /// Answer to an earlier [`crate::host::http_fetch`].
    fn http_response(&mut self, _response: HttpResponse) {}
    /// A network request matching the manifest's `request_filters`
    /// (`requests` permission). Synchronous and on the hot path: the budget
    /// is tiny, no KV, no network.
    fn request(&mut self, _req: RequestInput) -> RequestOutput {
        RequestOutput::allow()
    }
    /// A tab committed or finished loading (`tabs` permission and
    /// `events = ["navigation"]`).
    fn navigation(&mut self, _event: NavigationEvent) {}
    /// A palette command from the manifest's `[[commands]]`.
    fn command(&mut self, _input: CommandInput) {}
    /// The user typed the plugin's `omnibox_keyword`, then text.
    fn omnibox(&mut self, _input: OmniboxInput) -> OmniboxOutput {
        OmniboxOutput::default()
    }
    /// A call of one of the manifest's `[[tools]]` (MCP / AI assistant).
    fn mcp_tool(&mut self, input: McpToolInput) -> McpToolOutput {
        McpToolOutput::error(format!("unknown tool {}", input.name))
    }
    /// A web page called `window.__ferrosurf.call("plugin:<id>", payload)`.
    /// Returns the reply as a JSON string (`None`: `null`).
    fn page_message(&mut self, _input: PageMessageInput) -> Option<String> {
        None
    }
}

thread_local! {
    /// The last output buffer handed to the host; kept alive until the
    /// next call.
    static OUTPUT: RefCell<Vec<u8>> = const { RefCell::new(Vec::new()) };
}

/// `fs_alloc`: a buffer of `len` bytes the host writes a hook input into.
/// Ownership passes to the following [`dispatch`].
pub fn alloc(len: i32) -> i32 {
    let Ok(len) = usize::try_from(len) else {
        return 0;
    };
    let b: Box<[u8]> = vec![0u8; len.max(1)].into_boxed_slice();
    Box::into_raw(b) as *mut u8 as usize as i32
}

/// Takes back a buffer made by [`alloc`].
///
/// # Safety
/// `ptr`/`len` must come from one [`alloc`] call not yet taken back.
unsafe fn take_input(ptr: i32, len: i32) -> Box<[u8]> {
    let len = (len.max(0) as usize).max(1);
    let raw = core::ptr::slice_from_raw_parts_mut(ptr as usize as *mut u8, len);
    // SAFETY: guaranteed by the caller (the host passes back what
    // `fs_alloc` returned, with the same length).
    unsafe { Box::from_raw(raw) }
}

fn set_output(bytes: Vec<u8>) -> i64 {
    OUTPUT.with(|o| {
        let mut o = o.borrow_mut();
        *o = bytes;
        abi::pack(o.as_ptr() as usize as u32, o.len() as u32)
    })
}

fn output<T: serde::Serialize>(v: &T) -> i64 {
    match abi::encode(v) {
        Ok(b) => set_output(b),
        Err(_) => -1,
    }
}

/// Runs one hook: decodes the input, calls `plugin`, encodes the output.
/// Returns `fs_call`'s packed result (0 = no output, -1 = bad input).
///
/// # Safety
/// `ptr`/`len` must come from [`alloc`] (the host contract).
pub unsafe fn dispatch<P: Plugin>(plugin: &mut P, hook_id: i32, ptr: i32, len: i32) -> i64 {
    install_panic_hook();
    // SAFETY: forwarded from the caller.
    let input = unsafe { take_input(ptr, len) };
    let input = &input[..len.max(0) as usize];
    macro_rules! arg {
        ($t:ty) => {
            match abi::decode::<$t>(input) {
                Ok(v) => v,
                Err(_) => return -1,
            }
        };
    }
    match hook_id {
        hook::LOAD => plugin.load(arg!(LoadInfo)),
        hook::UNLOAD => plugin.unload(),
        hook::SETTING_CHANGED => {
            let s = arg!(SettingChanged);
            plugin.setting_changed(s.key, s.value);
        }
        hook::HTTP_RESPONSE => plugin.http_response(arg!(HttpResponse)),
        hook::REQUEST => return output(&plugin.request(arg!(RequestInput))),
        hook::NAVIGATION => plugin.navigation(arg!(NavigationEvent)),
        hook::COMMAND => plugin.command(arg!(CommandInput)),
        hook::OMNIBOX => return output(&plugin.omnibox(arg!(OmniboxInput))),
        hook::MCP_TOOL => return output(&plugin.mcp_tool(arg!(McpToolInput))),
        hook::PAGE_MESSAGE => {
            let reply_json = plugin
                .page_message(arg!(PageMessageInput))
                .unwrap_or_default();
            return output(&PageMessageOutput { reply_json });
        }
        _ => {}
    }
    0
}

fn install_panic_hook() {
    use std::sync::Once;
    static ONCE: Once = Once::new();
    ONCE.call_once(|| {
        std::panic::set_hook(Box::new(|info| {
            crate::host::log(crate::host::Level::Error, &format!("panic: {info}"));
        }));
    });
}

/// Exports `fs_abi_version`, `fs_alloc` and `fs_call` for a [`Plugin`]
/// type that implements `Default`.
#[macro_export]
macro_rules! register_plugin {
    ($ty:ty) => {
        thread_local! {
            static __FS_PLUGIN: ::core::cell::RefCell<$ty> =
                ::core::cell::RefCell::new(<$ty as ::core::default::Default>::default());
        }

        #[unsafe(no_mangle)]
        pub extern "C" fn fs_abi_version() -> i32 {
            $crate::abi::ABI_VERSION as i32
        }

        #[unsafe(no_mangle)]
        pub extern "C" fn fs_alloc(len: i32) -> i32 {
            $crate::guest::alloc(len)
        }

        #[unsafe(no_mangle)]
        pub extern "C" fn fs_call(hook: i32, ptr: i32, len: i32) -> i64 {
            __FS_PLUGIN.with(|p| {
                // SAFETY: the host passes back a buffer from `fs_alloc`.
                unsafe { $crate::guest::dispatch(&mut *p.borrow_mut(), hook, ptr, len) }
            })
        }
    };
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::abi::RequestAction;

    #[derive(Default)]
    struct Blocker;
    impl Plugin for Blocker {
        fn request(&mut self, req: RequestInput) -> RequestOutput {
            if req.url.contains("ads") {
                RequestOutput::block()
            } else {
                RequestOutput::allow()
            }
        }
    }

    // `dispatch` itself passes guest pointers as `i32`, so it only runs on
    // wasm32 (covered by the host crate's WAT tests and the examples).
    #[test]
    fn trait_defaults_and_overrides() {
        let mut p = Blocker;
        let r = |url: &str| RequestInput {
            url: url.into(),
            ..Default::default()
        };
        assert_eq!(p.request(r("https://ads.x/")).action, RequestAction::Block);
        assert_eq!(p.request(r("https://x/")).action, RequestAction::Allow);
        assert!(p.mcp_tool(McpToolInput::default()).is_error);
        assert_eq!(p.page_message(PageMessageInput::default()), None);
    }
}
